-- MotorcycleERP v4: operational modules, public catalog and audit trail.
-- Safe additive migration: does not drop, truncate or rewrite existing business tables.
BEGIN;
CREATE TABLE IF NOT EXISTS "WorkflowRecords" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Module" varchar(40) NOT NULL,
  "Title" varchar(240) NOT NULL,
  "Status" varchar(40) NOT NULL DEFAULT 'Open',
  "Description" text NULL,
  "ReferenceNo" varchar(100) NULL,
  "CustomerId" integer NULL,
  "MotorcycleId" integer NULL,
  "DealerId" integer NULL,
  "Amount" numeric(18,2) NULL,
  "Quantity" integer NULL,
  "DueAt" timestamptz NULL,
  "Payload" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "CreatedBy" varchar(120) NOT NULL DEFAULT '',
  "CreatedAt" timestamptz NOT NULL DEFAULT now(),
  "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_WorkflowRecords_Module_DueAt" ON "WorkflowRecords" ("Module", "DueAt");
CREATE INDEX IF NOT EXISTS "IX_WorkflowRecords_CustomerId" ON "WorkflowRecords" ("CustomerId");
CREATE TABLE IF NOT EXISTS "CatalogListings" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "MotorcycleId" integer NOT NULL UNIQUE REFERENCES "Motorcycles"("Id") ON DELETE RESTRICT,
  "PublicDescription" text NULL,
  "ImageUrls" jsonb NOT NULL DEFAULT '[]'::jsonb,
  "IsPublished" boolean NOT NULL DEFAULT false,
  "UpdatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS "AuditLogs" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "Username" varchar(120) NOT NULL,
  "Action" varchar(40) NOT NULL,
  "Entity" varchar(80) NOT NULL,
  "EntityId" varchar(80) NOT NULL,
  "Details" text NULL,
  "CreatedAt" timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "IX_AuditLogs_CreatedAt" ON "AuditLogs" ("CreatedAt");
COMMIT;
